import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public class GotchasMasteryDemo {

    // Mutable key that breaks HashMap invariants
    static class MutableKey {
        String id;
        MutableKey(String id) { this.id = id; }
        @Override public int hashCode() { return Objects.hash(id); }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof MutableKey)) return false;
            return Objects.equals(id, ((MutableKey) o).id);
        }
        @Override public String toString() { return "Key(" + id + ")"; }
    }

    public static void main(String[] args) {
        // 1. Mutable Key Gotcha
        Map<MutableKey, String> sessionMap = new HashMap<>();
        MutableKey userKey = new MutableKey("SESSION_101");
        sessionMap.put(userKey, "Alice");
        System.out.println("Lookup before mutation: " + sessionMap.get(userKey));

        // Mutating key field alters hashCode()!
        userKey.id = "SESSION_999";
        System.out.println("Lookup AFTER mutation: " + sessionMap.get(userKey)); // returns null!
        System.out.println("Map contains key? " + sessionMap.containsKey(userKey)); // false!
        System.out.println("Map size (orphaned memory): " + sessionMap.size()); // 1!

        // 2. The subList Invalidation Trap
        List<String> logs = new ArrayList<>(Arrays.asList("log1", "log2", "log3", "log4"));
        List<String> slice = logs.subList(1, 3);
        System.out.println("Slice before modification: " + slice);

        // Direct mutation to parent list invalidates slice
        logs.add("log5");
        try {
            slice.get(0); // throws CME
        } catch (Exception e) {
            System.out.println("Caught expected subList invalidation: " + e.getClass().getSimpleName());
        }

        // 3. Arrays.asList Primitive Array Trap
        int[] primitives = {10, 20, 30};
        List<int[]> boxedList = Arrays.asList(primitives);
        System.out.println("Arrays.asList(int[]) size: " + boxedList.size()); // 1, NOT 3!
        System.out.println("Element 0 type: " + boxedList.get(0).getClass().getSimpleName());

        // Correct conversion for primitives:
        List<Integer> correctList = Arrays.stream(primitives).boxed().toList();
        System.out.println("Correct boxed list: " + correctList + " (size: " + correctList.size() + ")");
    }
}
```

