import java.util.ArrayList;
import java.util.List;

public class SubListSafeExtractor {
    public static List<String> getDetachedSubList(List<String> source, int fromIndex, int toIndex) {
        if (source == null || fromIndex < 0 || toIndex > source.size() || fromIndex > toIndex) {
            throw new IllegalArgumentException("Invalid range or null source");
        }
        return new ArrayList<>(source.subList(fromIndex, toIndex));
    }
}

