import java.util.ArrayList;
import java.util.List;

public class VarargsSafety {
    @SafeVarargs
    public static <T> List<T> safeCollect(T... items) {
        if (items == null || items.length == 0) {
            return List.of();
        }
        List<T> list = new ArrayList<>();
        for (T item : items) {
            if (item != null) {
                list.add(item);
            }
        }
        return List.copyOf(list);
    }
}

