import java.util.Map;

public class KeySecurityDemo {
    public record SecureKey(String tenantId, String resourceId) {}

    public static String getLookupKey(Map<SecureKey, String> map, String tenantId, String resourceId) {
        if (map == null || tenantId == null || resourceId == null) return null;
        return map.get(new SecureKey(tenantId, resourceId));
    }
}
